function header(p) {
 const mega=groups.map(([label,slug,children])=>`<div><a class="mega-title" href="${link(p,slug)}">${label}</a>${children.map(s=>`<a href="${link(p,s)}">${esc(collections[s]?.title||s)}</a>`).join('')}</div>`).join('');
 return `<div class="announcement">Little moments. Big happiness. · Personalised gifts & thoughtful supplies</div><header class="header"><div class="wrap nav-row"><a class="brand" href="${p}" aria-label="Hamperia Solutions home"><img class="brand-logo" src="${p}assets/hamperia-solutions-logo.webp" alt="" width="58" height="58"><span class="brand-name">Hamperia<small>SOLUTIONS</small></span></a><form class="header-search" role="search" action="${p}search/"><label class="sr-only" for="site-search">Search gifts and supplies</label><input id="site-search" name="q" type="search" placeholder="Find your kind of thoughtful…"><button aria-label="Search products" type="submit">Search</button></form><button class="menu" aria-controls="navigation" aria-expanded="false" type="button">Menu ☰</button><nav class="nav-links" id="navigation" aria-label="Main navigation"><a href="${p}">Home</a><a href="${p}hamperia/">Hamperia Store</a><a href="${p}hampers/">Personalised Hampers</a><details class="corporate-menu"><summary>Corporate & Bulk Gifting</summary><div class="mega-menu"><a class="mega-overview" href="${p}corporate-bulk-gifting/">Explore corporate & bulk gifting →</a><div class="mega-grid">${mega}</div></div></details><a href="${p}tutorials/">Learn to Make</a><a href="${p}blog/">Blog</a></nav><div class="auth-controls" aria-label="Account"><a class="auth-link auth-guest" href="${p}auth/">Sign in</a><details class="auth-user profile-menu" hidden><summary class="profile-trigger"><svg aria-hidden="true" viewBox="0 0 24 24" width="19" height="19" fill="none" stroke="currentColor" stroke-width="1.7"><circle cx="12" cy="8" r="3.3"></circle><path d="M5.5 20c.6-3.5 3-5.5 6.5-5.5s5.9 2 6.5 5.5"></path></svg><span class="auth-user-name" aria-label="Signed in as"></span><span class="profile-chevron" aria-hidden="true">⌄</span></summary><div class="profile-dropdown"><a data-auth-dashboard href="${p}account/">My account</a><button data-signout type="button">Sign out</button></div></details></div></div></header>`;
}
function footer(p){return `<footer class="footer"><div class="wrap"><div class="footer-top"><div><h2>Made to mean more.</h2><p>Personalised hampers, creative supplies and thoughtful corporate gifts.</p><p class="footer-browse"><a href="${p}">Home</a> · <a href="${p}hamperia/">Hamperia Store</a> · <a href="${p}hampers/">Personalised Hampers</a> · <a href="${p}corporate-bulk-gifting/">Corporate gifting</a></p></div><div class="footer-contact"><a href="mailto:contact@hamperiasolutions.com">contact@hamperiasolutions.com</a><p><a href="${p}bulk-orders/">Request a quotation</a> · <a href="${p}blog/">Ideas & guides</a></p></div></div><div class="footer-bottom"><span>© 2026 Hamperia Solutions</span><span>Little moments. Big happiness.</span></div></div></footer>`}
function page(slug,title,description,body,{noindex=false,scripts=[]}={}){
 if (metadata[slug]) [title,description] = metadata[slug];
 const seoProduct = products.find(product => slug === 'products/'+product.slug);
 if (seoProduct) [title,description] = productMetadata(seoProduct);
 title = title.replace(/ \| Hamperia(?: Solutions)?$/, '');
 const structured = noindex ? '' : schema(slug,title,description,products,posts,collections);
 const shareImage = products.find(p=>slug==='products/'+p.slug)?.image || posts.find(p=>slug==='blog/'+p.slug)?.image || 'personalised-gift-hamper-inspiration.webp';
 const p='../'.repeat(slug.split('/').filter(Boolean).length)||'./';
 return `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(title)} | Hamperia</title><meta name="description" content="${esc(description)}"><link rel="canonical" href="https://hamperiasolutions.com/${slug?slug+'/':''}">${noindex?'<meta name="robots" content="noindex,follow">':''}<meta property="og:title" content="${esc(title)}"><meta property="og:description" content="${esc(description)}"><meta property="og:image" content="https://hamperiasolutions.com/assets/${shareImage}">${structured}<meta property="og:url" content="https://hamperiasolutions.com/${slug?slug+'/':''}"><link rel="stylesheet" href="${p}css/style.css"><link rel="stylesheet" href="${p}css/branding.css"><link rel="stylesheet" href="${p}css/auth.css"><link rel="stylesheet" href="${p}css/storefront.css"><script src="${p}js/main.js" defer></script><script src="https://cdn.jsdelivr.net/npm/@supabase/supabase-js@2" defer></script><script src="${p}js/auth.js" defer></script><script src="${p}js/catalog-filter.js" defer></script><script src="${p}js/storefront.js" defer></script>${scripts.map(s=>'<script src="'+p+'js/'+s+'" defer></script>').join('')}</head><body><a class="skip" href="#main">Skip to content</a>${header(p)}<main id="main">${body.includes('data-auth-status') ? '' : '<p class="auth-status wrap" data-auth-status role="status"></p>'}${body}</main>${footer(p)}</body></html>`;
}
const intro=(title,description,p='../',parent)=>`<section class="wrap collection-intro"><p class="eyebrow"><a href="${p}">Home</a>${parent ? ` / <a href="${p}${parent.slug}/">${esc(parent.title)}</a>` : ''} / ${esc(title)}</p><h1>${esc(title)}</h1><p>${esc(description)}</p></section>`;
const productKind=(category)=>category==='hamper'?'Personalised hamper':category==='kit'?'Employee welcome kit':'Hamper-making supply';
const isProductArt=(image)=>/^(essential-employee-|premium-employee-|signature-employee-|.*diwali-)/.test(image);
const card=(item,p='../')=>`<article class="shop-card" data-product-card data-product-slug="${item.slug}" data-name="${esc([item.name,...item.contents,...item.tags].join(" ").toLowerCase())}" data-price="${item.price}" data-category="${item.category}"><a href="${p}products/${item.slug}/"><span class="shop-card-image"><img class="${isProductArt(item.image)?'product-art':''}" src="${p}assets/${item.image}" alt="${esc(item.imageAlt)}" loading="lazy" width="600" height="500"></span><div class="shop-card-body"><span class="eyebrow">${productKind(item.category)}</span><h3>${esc(item.name)}</h3><p class="card-contents">${esc(item.contents.slice(0,3).join(" · "))}</p><p data-product-price>₹${item.price.toLocaleString('en-IN')} </p><span class="shop-card-link">View details ↗</span></div></a><div class="commerce-actions"><button class="wish-button" type="button" data-wish-key="catalog:${item.slug}" data-product-name="${esc(item.name)}" aria-label="Add to wishlist: ${esc(item.name)}" aria-pressed="false">♡</button><button class="add-button" type="button" data-cart-key="catalog:${item.slug}">Add to cart</button></div></article>`;
const cards=(items,p='../',catalog=false)=>`<div class="shop-grid"${catalog?' data-catalog-grid':''}>`+items.map(x=>x.slug.startsWith('dry-fruit-') ? card(x,p).replace('<span class="shop-card-link">','<small data-product-stock>10 available</small><span class="shop-card-link">') : card(x,p)).join('')+'</div>';
const quote=(topic,p='../')=>p+'bulk-orders/?collection='+encodeURIComponent(topic);
const collectionImages = {
 'employee-gifts': [['essential-employee-welcome-kit-999.webp','Essential welcome kit'],['premium-employee-welcome-kit-1899.webp','Premium welcome kit'],['signature-employee-welcome-kit-2999.webp','Signature welcome kit']],
 'client-gifts': [['golden-chocolate-candle-celebration-hamper.webp','Celebration gift'],['three-glass-jar-dry-fruit-gift-box-1099.webp','Three-jar dry fruit gift'],['executive-corporate-planner-coffee-gift-box.webp','Executive corporate gift']],
 'dry-fruit-hampers': [['two-glass-jar-dry-fruit-gift-box-699.webp','Two-jar gift box'],['three-glass-jar-dry-fruit-gift-box-1099.webp','Three-jar gift box'],['four-glass-jar-dry-fruit-gift-box-1499.webp','Four-jar gift box']],
 'chocolate-hampers': [['chocolate-hamper-concept.webp','Chocolate hamper inspiration'],['golden-chocolate-candle-celebration-hamper.webp','Chocolate celebration hamper'],['premium-corporate-diwali-gift-hamper-2499.webp','Festive chocolate hamper']],
 'wellness-hampers': [['wellness-hamper-concept.webp','Wellness hamper inspiration'],['green-premium-diwali-gift-hamper-3499.webp','Festive candle hamper'],['premium-corporate-diwali-gift-hamper-2499.webp','Diwali wellness gifting']]
};
const inspirationExamples = {
 'gourmet-hampers': [
  ['gourmet-hamper-inspiration.webp','Coffee & confectionery box','A coffee, biscuit, chocolate and preserve pairing.'],
  ['chocolate-hamper-concept.webp','Sweet afternoon box','A chocolate-led gift with room for a favourite drink.']
 ],
 'healthy-hampers': [
  ['healthy-hamper-inspiration.webp','Everyday nourishment box','Granola, nuts, herbal tea and dried fruit inspiration.'],
  ['two-glass-jar-dry-fruit-gift-box-699.webp','Two-jar dry-fruit gift','A compact nut and dried-fruit gift to personalise.'],
  ['four-glass-jar-dry-fruit-gift-box-1499.webp','Four-jar sharing gift','A larger dry-fruit presentation for a group.']
 ],
 'wellness-hampers': [
  ['wellness-hamper-inspiration.webp','Quiet evening box','Candle, tea, journal and a little time to unwind.']
 ]
};
function collectionExtras(c) {
 if (c.slug === 'employee-welcome-kits') return `<section class="wrap section"><h2>Compare welcome kits for new joiners</h2><p>Choose practical first-day essentials, then discuss your company branding and preferred colours.</p><div style="overflow-x:auto"><table class="collection-comparison"><thead><tr><th scope="col">Kit</th><th scope="col">Listed price</th><th scope="col">Included items</th></tr></thead><tbody>${products.filter(p=>p.category==='kit').sort((a,b)=>a.price-b.price).map(p=>`<tr><th scope="row"><a href="../products/${p.slug}/">${esc(p.name)}</a></th><td>₹${p.price.toLocaleString('en-IN')}</td><td>${esc(p.contents.join(', '))}</td></tr>`).join('')}</tbody></table></div><p>Confirm colours, branding and quantities before ordering. Customisation requires a separate quote.</p></section>`;
 if (c.slug === 'corporate-merchandise') {
  const names=['Water bottles','Tumblers','Mugs','Keychains','T-shirts','Hoodies'];
  return `<section class="wrap section collection-feature"><div><p class="eyebrow">Brand it your way</p><h2>Everyday merchandise, made yours.</h2><p>Choose the items, colours and logo placement. We will confirm print method, minimum quantity and a sample before production.</p><a class="button secondary" href="${quote('Corporate merchandise')}">Request a merchandise quote</a></div><img src="../assets/corporate-merchandise-concept.webp" alt="Bottle, tumbler, mug, keychain, T-shirt and hoodie merchandise examples" loading="lazy" width="600" height="600"></section><section class="wrap merch-grid" aria-label="Merchandise options">${names.map((name,i)=>`<article class="merch-tile" data-collection-example><div class="merch-crop merch-crop-${i+1}" aria-hidden="true"></div><h3>${name}</h3><p>Custom logo options · Price on request</p></article>`).join('')}</section>`;
 }
 if (c.slug === 'chocolate-hampers' || c.slug === 'wellness-hampers') {
  const chocolate = c.slug === 'chocolate-hampers';
  const image = chocolate ? 'chocolate-hamper-concept.webp' : 'wellness-hamper-concept.webp';
  const title = chocolate ? 'Build a box around their favourite chocolates.' : 'A quiet moment, beautifully boxed.';
  const detail = chocolate ? 'Choose chocolate styles, wrapping and a personal note. We will confirm the exact assortment, allergens, transit suitability and price in a custom quote.' : 'Combine a candle, a comforting drink, a journal or other calming touches. Fragrance preferences, final contents and price are confirmed in a custom quote.';
  return `<section class="wrap section collection-feature"><div><p class="eyebrow">Made for your recipient · Price on request</p><h2>${title}</h2><p>${detail}</p><a class="button secondary" href="${quote(c.title)}">Plan this hamper ↗</a></div><img src="../assets/${image}" alt="Illustrative ${c.title.toLowerCase()} concept" loading="lazy" width="600" height="600"></section>`;
 }
 const images=collectionImages[c.slug];
 return images ? `<section class="wrap section collection-gallery"><div class="section-heading"><div><p class="eyebrow">See the possibilities</p><h2>${c.slug === 'dry-fruit-hampers' ? 'Choose your box size.' : 'Thoughtful details, in every gift.'}</h2></div><p>Illustrative product photography. Check the product page and confirm final contents before payment.</p></div><div class="collection-gallery-grid">${images.map(([image,alt])=>{const product=products.find(p=>p.image===image||p.originalImage===image);return product?`<a href="../products/${product.slug}/"><img src="../assets/${product.image}" alt="${esc(alt)}" loading="lazy" width="500" height="500"><span>View ${esc(product.name)} →</span></a>`:`<img src="../assets/${image}" alt="${esc(alt)}" loading="lazy" width="500" height="500">`;}).join('')}</div></section>` : '';
}
const filters='<div class="store-filters"><label>Search products<input type="search" data-product-search placeholder="Try ribbon, crate or chocolate"></label><label>Budget<select data-product-budget><option value="">Any price</option><option value="1000">Up to ₹1,000</option><option value="1500">Up to ₹1,500</option><option value="2500">Up to ₹2,500</option></select></label><label>Sort by<select data-product-sort><option value="default">Featured</option><option value="low">Price: low to high</option><option value="high">Price: high to low</option></select></label><p data-result-count role="status"></p></div>';
function collectionBody(c) {
 const items=products.filter(x=>c.limit?x.price<c.limit:x.tags.includes(c.slug));
 const ideas=(inspirationExamples[c.slug]||[]).slice(0,Math.max(0,3-items.length));
 const ideaCards=ideas.length?`<div class="shop-grid inspiration-grid">${ideas.map(([image,title,description])=>`<article class="shop-card inspiration-card" data-collection-example><img src="../assets/${image}" alt="Illustrative ${esc(title)}" loading="lazy" width="600" height="500"><div class="shop-card-body"><span class="eyebrow">Made-to-order idea · Price on request</span><h3>${esc(title)}</h3><p>${esc(description)} Final contents, price and availability are confirmed in your quote.</p><a class="shop-card-link" href="${quote(title)}">Enquire about this idea ↗</a></div></article>`).join('')}</div>`:'';
 return intro(c.title,c.intro,'../',{slug:'corporate-bulk-gifting',title:'Corporate & Bulk Gifting'})+`<section class="wrap section" data-collection-slug="${c.slug}"><div class="section-heading"><h2>${items.length?'Explore the collection':'Explore the possibilities'}</h2><p>${items.length?'Listed product prices. Images show presentation inspiration.':'Made-to-order ideas are shown below. Request a quote to confirm contents, price and availability.'}</p></div>${items.length?filters:''}${cards(items,'../',true)}<p data-no-results hidden>No matching gifts. Try another budget or search.</p>${ideaCards}${!items.length&&!ideas.length?'<a class="button secondary" href="'+quote(c.title)+'">Discuss your requirements</a>':''}</section><section class="wrap collection-story"><div><p class="eyebrow">Thoughtfully selected</p><h2>${esc(c.heading)}</h2><p>${esc(c.advice)}</p><p>${esc(c.planning)}</p><a class="button" href="${quote(c.title)}">Request a bulk quote ↗</a></div><aside><h3>Plan your gift</h3><ul>${c.features.map(f=>'<li>'+esc(f)+'</li>').join('')}</ul><p>Contents, availability, personalisation and delivery are confirmed before ordering.</p></aside></section>${collectionExtras(c)}${categoryGuide(c,items,commerceConfig.shippingPaise)}<section class="wrap faq"><h2>Before you order</h2><details><summary>${esc(c.question)}</summary><p>${esc(c.answer)}</p></details><details><summary>How do I confirm my order?</summary><p>Send an enquiry with quantity, required date and delivery location. Review the final contents and quotation before confirming. Use the basket for listed products when checkout is available. Custom requests require a separate quote.</p></details><p><a href="../corporate-bulk-gifting/">Explore all corporate collections →</a> · <a href="../blog/corporate-gifting-planning-checklist/">Read the gifting checklist →</a></p></section>`;
}
for(const c of Object.values(collections)) write(c.slug,page(c.slug,c.title,c.intro,collectionBody(c)));
for (const [oldSlug, destination] of [['bulk-gifting','corporate-gifting'],['bulk-diwali-gifts','corporate-diwali-gifts']]) write(oldSlug,`<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="robots" content="noindex,follow"><meta http-equiv="refresh" content="0;url=../${destination}/"><link rel="canonical" href="https://hamperiasolutions.com/${destination}/"><title>Moved | Hamperia Solutions</title></head><body><p>This collection has moved to <a href="../${destination}/">${destination.replaceAll('-',' ')}</a>.</p></body></html>`);
const tileImages={"corporate-gifting":"executive-corporate-planner-coffee-gift-box.webp","employee-welcome-kits":"premium-employee-welcome-kit-1899.webp","diwali-gifts":"premium-corporate-diwali-gift-hamper-2499.webp","gift-hampers":"golden-chocolate-candle-celebration-hamper.webp","shop-by-budget":"two-glass-jar-dry-fruit-gift-box-699.webp"};
const tiles=groups.map(([title,slug,children])=>`<article class="collection-tile">${tileImages[slug]?`<a href="../${slug}/"><img src="../assets/${({'employee-welcome-kits':'welcome-premium-studio.webp','diwali-gifts':'diwali-celebration-studio.webp'})[slug]||tileImages[slug]}" alt="${esc(title)}" loading="lazy" width="600" height="400"></a>`:""}<h2><a href="../${slug}/">${title} ↗</a></h2><ul>${children.map(s=>'<li><a href="../'+s+'/">'+esc(collections[s]?.title||s)+'</a></li>').join('')}</ul></article>`).join('');
write('corporate-bulk-gifting',page('corporate-bulk-gifting','Corporate & Bulk Gifting','Explore corporate gifts, welcome kits, Diwali collections and bulk hamper enquiries.',intro('Good gifts. Great connections.','Explore corporate and bulk gifting by recipient, occasion and budget.')+'<section class="wrap collection-grid">'+tiles+'</section>'));
write('shop-by-budget',page('shop-by-budget','Shop Gifts by Budget','Compare gift collections by budget and request a tailored quotation.',intro('A thoughtful gift, at your price.','Choose a budget to see listed hamper combinations. Flat ₹99 shipping is added at checkout; custom changes require a separate quote.')+'<section class="wrap budget-links">'+[500,1000,1500,2000,2500].map(n=>'<a href="../gifts-under-'+n+'/">Under ₹'+n.toLocaleString('en-IN')+' ↗</a>').join('')+'</section>'));
for(const product of products){
 const parent = product.category==='kit' ? {slug:'employee-welcome-kits',title:'Employee Welcome Gifts'} : product.category==='hamper' ? {slug:'hampers',title:'Personalised Hampers'} : {slug:'hamperia',title:'Hamperia Store'};
 const contents=product.contents.length?`<section class="product-contents" data-product-contents><h3>What's inside</h3><ul>${product.contents.map(item=>`<li>${esc(item)}</li>`).join('')}</ul><p class="product-contents-note">Please confirm exact brands, quantities, colours and any substitutions before ordering.</p></section>`:'';
 const body=`<div class="wrap product-breadcrumb"><a href="../../">Home</a> / <a href="../../${parent.slug}/">${parent.title}</a> / ${esc(product.name)}</div>`+`<section class="wrap product-detail">${studio.gallery(product)}<div><p class="eyebrow">${productKind(product.category)}</p><h1 class="product-title">${esc(product.name)}</h1><h2>₹${product.price.toLocaleString('en-IN')}</h2><p data-product-description>${esc(product.description)}</p>${contents}${studio.personalisation("catalog:"+product.slug,{branding:product.category!=="supplies"})}<label class="quantity-picker">Quantity<input data-add-quantity type="number" min="1" max="10" value="1" step="1"></label><div class="commerce-actions detail-actions"><button class="wish-button" type="button" data-wish-key="catalog:${product.slug}" data-product-name="${esc(product.name)}" aria-label="Add to wishlist: ${esc(product.name)}" aria-pressed="false">♡</button><button class="add-button" type="button" data-cart-key="catalog:${product.slug}">Add to cart</button><button class="button secondary" type="button" data-cart-key="catalog:${product.slug}" data-buy-now>Buy now</button></div><p>Tell us your required date, preferred colours and personal message. The product image shows the proposed presentation; the final presentation is agreed in your quotation.</p><a class="button secondary" data-product-enquiry="catalog:${product.slug}" data-product-title="${esc(product.name)}" href="mailto:contact@hamperiasolutions.com?subject=${encodeURIComponent('Product enquiry: '+product.name)}">Enquire about personalisation ↗</a>${studio.deliveryDetails()}<p class="form-help">Flat ₹99 shipping is added at checkout. Customisation may require a separate quote.</p><a href="../../${parent.slug}/">Back to ${parent.title} →</a></div></section>`;
 const related=products.filter(x=>x.slug!==product.slug&&x.category===product.category&&x.tags.some(t=>product.tags.includes(t))).slice(0,3);
 write('products/'+product.slug,page('products/'+product.slug,product.name,product.description,body+`<section class="wrap section"><div class="section-heading"><h2>You might also love.</h2></div>${cards(related,'../../')}</section>`));
}
write('products/item',page('products/item','Product details','See the latest price, image and availability for this Hamperia product.',`<section class="wrap section" data-catalog-detail><p role="status">Loading product details…</p></section><template data-personalisation-template>${studio.personalisation('dynamic')}</template>`,{noindex:true}));

