 '<div class="wrap builder-back-links"><a href="../">← Back to home</a><a href="../hampers/">Browse complete hampers →</a></div>'+
 '<section class="wrap builder-layout" data-hamper-builder><div class="builder-choice-panel"><p class="eyebrow">Make it your own</p><h2>Build a hamper in three steps.</h2><p>Choose your pieces and we will turn your selection into a clear custom-gift brief. Tap a choice again or use Remove in the preview to change it.</p><nav class="builder-progress" aria-label="Hamper building steps"><a href="#builder-base">1. Choose a base</a><a href="#builder-contents">2. Add gifts</a><a href="#builder-decor">3. Finish it</a><a href="#hamper-preview">Your preview ↓</a></nav><button type="button" class="button secondary" data-builder-import hidden>Use this shared design</button><div data-builder-options></div></div><aside class="builder-preview-panel" id="hamper-preview"><p class="eyebrow">Your live preview</p><h2>Your hamper, taking shape.</h2><div data-builder-visual></div><div data-builder-summary aria-live="polite"></div><div class="builder-save-tools"><button type="button" class="button secondary" data-builder-share disabled>Copy design link</button><p>Your choices are saved to your account on this browser. Shared links include product choices only.</p></div><p class="builder-disclaimer">This visual is an illustration, not a photo of the exact finished hamper. Contents, quantities and price are confirmed in your quote.</p>'+studio.personalisation('builder')+'<div class="builder-purchase-choices"><section><h3>Have Hamperia make it</h3><p>We will confirm the complete hamper, assembly, price and delivery before you order.</p><a class="button" data-builder-enquiry href="mailto:contact@hamperiasolutions.com">Request complete hamper quote ↗</a></section><section><h3>Make it yourself</h3><p>Add individually listed supplies to your basket and assemble your hamper at home. Online payment is still being set up.</p><div data-builder-available></div><a class="button secondary" href="#hamperia-supplies">Shop individual supplies ↓</a></section></div></aside></section><section class="wrap section" id="hamperia-supplies"><div class="section-heading"><div><p class="eyebrow">The finishing touches</p><h2>Shop hamper-making supplies.</h2></div><p>Available individual supplies are listed with their own prices below.</p></div><div class="host-store-action" data-producer-access hidden><a class="button" href="../producer/?category=diy">Add a product to Hamperia</a></div>'+filters+cards(products.filter(p=>!['hamper','kit'].includes(p.category)))+'<p data-no-results hidden>No matching supplies. Try another search.</p></section><section class="wrap catalog" data-approved-products="diy" hidden><h2>From our approved makers</h2><div class="products"></div></section>';
